package org.viridexa.api.account;
import java.net.*;import java.net.http.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.test.context.*;import org.springframework.boot.json.JsonParserFactory;
import static org.junit.jupiter.api.Assertions.*;
/** Portable SQL and REST verified on isolated MySQL, not represented as a TiDB cloud test. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class PortableAccountMySqlIT {
 @LocalServerPort int port;
 static String env(String k){return Objects.requireNonNull(System.getenv(k),k);}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){if(!env("TIDB_TEST_SCHEMA").startsWith("viridexa_tidb_test_"))throw new IllegalStateException("Production forbidden");r.add("spring.datasource.url",()->env("TIDB_TEST_DB_URL"));r.add("spring.datasource.username",()->env("TIDB_TEST_RO"));r.add("spring.datasource.password",()->env("TIDB_TEST_PASSWORD"));r.add("spring.flyway.enabled",()->false);r.add("viridexa.accounts.registration-mode",()->"portable");r.add("viridexa.accounts.username",()->env("TIDB_TEST_ACCOUNT"));r.add("viridexa.accounts.password",()->env("TIDB_TEST_PASSWORD"));r.add("viridexa.review.username",()->env("TIDB_TEST_RO"));r.add("viridexa.review.password",()->env("TIDB_TEST_PASSWORD"));r.add("viridexa.agent.runtime-directory",()->env("TIDB_TEST_RUNTIME"));}
 Connection db(String user)throws Exception{return DriverManager.getConnection(env("TIDB_TEST_DB_URL"),user,env("TIDB_TEST_PASSWORD"));}
 void sql(String text)throws Exception{try(var c=db(env("TIDB_TEST_MIGRATOR"));var s=c.createStatement()){s.execute(text);}}
 long count(String text)throws Exception{try(var c=db(env("TIDB_TEST_MIGRATOR"));var s=c.createStatement();var r=s.executeQuery(text)){assertTrue(r.next());return r.getLong(1);}}
 HttpClient client(){return HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();}
 HttpResponse<String> get(HttpClient c,String path)throws Exception{return c.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).GET().build(),HttpResponse.BodyHandlers.ofString());}
 HttpResponse<String> register(HttpClient c,String email)throws Exception{String csrf=(String)JsonParserFactory.getJsonParser().parseMap(get(c,"/api/v1/csrf").body()).get("token");String body="{\"email\":\""+email+"\",\"displayName\":\"隔离兼容测试\",\"password\":\""+env("TIDB_TEST_ACCOUNT_PASSWORD")+"\"}";return c.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/account/register")).header("Content-Type","application/json").header("X-CSRF-TOKEN",csrf).POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 String mail(){return "portable-fixture-"+UUID.randomUUID()+"@example.invalid";}
 @AfterEach void cleanup()throws Exception{sql("UPDATE app_role SET role_key='MEMBER' WHERE role_key='MEMBER_HOLD'");sql("DELETE p FROM public_member_account p JOIN app_user u ON u.id=p.user_id WHERE u.email LIKE 'portable-fixture-%@example.invalid'");sql("DELETE ur FROM user_role ur JOIN app_user u ON u.id=ur.user_id WHERE u.email LIKE 'portable-fixture-%@example.invalid'");sql("DELETE FROM app_user WHERE email LIKE 'portable-fixture-%@example.invalid'");}
 @Test void registrationHasOnlyMemberAndCannotOpenAdmin()throws Exception{var c=client();var response=register(c,mail());assertEquals(201,response.statusCode());assertTrue(response.body().contains("MEMBER"));assertFalse(response.body().contains("ADMIN"));assertEquals(403,get(c,"/api/v1/admin/session").statusCode());assertEquals(1,count("SELECT COUNT(*) FROM public_member_account"));assertEquals(0,count("SELECT COUNT(*) FROM user_role"));}
 @Test void duplicateDoesNotLeaveOrphan()throws Exception{String e=mail();assertEquals(201,register(client(),e).statusCode());assertEquals(409,register(client(),e).statusCode());assertEquals(1,count("SELECT COUNT(*) FROM app_user"));assertEquals(1,count("SELECT COUNT(*) FROM public_member_account"));}
 @Test void missingFixedRoleRollsBack()throws Exception{sql("UPDATE app_role SET role_key='MEMBER_HOLD' WHERE role_key='MEMBER'");assertEquals(503,register(client(),mail()).statusCode());assertEquals(0,count("SELECT COUNT(*) FROM app_user"));}
 @Test void enrollmentFailureRollsBackInsertedUser()throws Exception{String schema=env("TIDB_TEST_SCHEMA"),account=env("TIDB_TEST_ACCOUNT");sql("REVOKE INSERT(user_id) ON "+schema+".public_member_account FROM '"+account+"'@'%'");try{assertEquals(503,register(client(),mail()).statusCode());assertEquals(0,count("SELECT COUNT(*) FROM app_user"));}finally{sql("GRANT INSERT(user_id) ON "+schema+".public_member_account TO '"+account+"'@'%'");}}
 @Test void concurrentRegistrationHasOneCompleteEnrollment()throws Exception{String e=mail();var executor=Executors.newFixedThreadPool(2);try{var futures=executor.invokeAll(List.of((Callable<Integer>)()->register(client(),e).statusCode(),()->register(client(),e).statusCode()));var codes=new ArrayList<Integer>();for(var f:futures)codes.add(f.get());Collections.sort(codes);assertEquals(List.of(201,409),codes);assertEquals(1,count("SELECT COUNT(*) FROM public_member_account"));}finally{executor.shutdownNow();}}
 @Test void accountIdentityCannotGrantRolesOrModifyScience()throws Exception{assertEquals(201,register(client(),mail()).statusCode());try(var c=db(env("TIDB_TEST_ACCOUNT"));var s=c.createStatement()){assertThrows(SQLException.class,()->s.execute("INSERT INTO user_role(user_id,role_id) SELECT u.id,r.id FROM app_user u CROSS JOIN app_role r WHERE r.role_key='ADMIN'"));assertThrows(SQLException.class,()->s.execute("UPDATE scientific_candidate SET reason='isolated attempt'"));assertThrows(SQLException.class,()->s.execute("INSERT INTO app_user(email,display_name,password_hash,enabled) VALUES('portable-fixture-forbidden@example.invalid','isolated','isolated',FALSE)"));}}
 @Test void mysqlProcedurePathRemainsAvailable()throws Exception{var legacy=new AccountStore(env("TIDB_TEST_DB_URL"),env("TIDB_TEST_ACCOUNT"),env("TIDB_TEST_PASSWORD"),"procedure");try{String e=mail();legacy.register(e,"isolated legacy fixture","isolated-not-a-login-hash");Long id=legacy.jdbc().queryForObject("SELECT id FROM app_user WHERE email=?",Long.class,e);assertEquals(List.of("MEMBER"),AccountRoles.read(legacy.jdbc(),id,false));assertEquals(0,count("SELECT COUNT(*) FROM public_member_account"));}finally{legacy.close();}}

}
